/**
 * @distilled.cloud/tailscale -- Tailscale SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * in `.generated-specs` (written by `scripts/convert.ts` from the OpenAPI
 * spec). Everything else in this folder is hand-written.
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as Tailscale from "@distilled.cloud/tailscale";
 *
 * const program = Effect.gen(function* () {
 *   const policy = yield* Tailscale.getPolicyFile({ tailnet: "-" });
 *   return policy.eTag;
 * });
 *
 * const Live = Tailscale.CredentialsFromEnv.pipe(
 *   Layer.provideMerge(FetchHttpClient.layer),
 * );
 *
 * program.pipe(Effect.provide(Live), Effect.runPromise);
 * ```
 */
